Q_Msg * q_remove (Q q , TskTimeout timeout)
{
  MbxMsg * msg ;
  
  if (os_irq_executing)
  	msg = os_mbx_rcev_i (q->mbx) ;
  else
  	msg = os_mbx_rcev   (q->mbx , timeout) ;

  return msg ? cast_mbx_msg_to_q_msg (msg) : 0  ;
} 

